import (
	"fmt"
	"strings"
)

var numbers = map[int]string{
	0: "no", 1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
	6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
}

// title capitalizes the first letter of s and leaves the rest unchanged.
func title(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

// bottlePhrase returns a phrase like "Ten green bottles" or "one green bottle".
func bottlePhrase(n int) string {
	singular := "bottle"
	if n != 1 {
		singular = "bottles"
	}
	return title(numbers[n]) + " green " + singular
}

func Recite(startBottles, takeDown int) []string {
	var verses []string
	for n := startBottles; n > startBottles-takeDown; n-- {
		verse := []string{
			bottlePhrase(n) + " hanging on the wall,",
			bottlePhrase(n) + " hanging on the wall,",
			"And if one green bottle should accidentally fall,",
			"There'll be " + bottlePhrase(n-1) + " hanging on the wall.",
		}
		verses = append(verses, verse...)
		if n > startBottles-takeDown {
			verses = append(verses, "")
		}
	}
	return verses
}

